#!/usr/bin/env bash
# One-time setup: create the public repo that hosts PR decks on GitHub Pages.
# Usage: create_deck_repo.sh [owner/name]   (default OpenC3/pr-decks)
#
# Decks land at <owner>/<repo>/pr-<n>/<sha>/ so one Pages site serves decks for
# PRs from any source repo.
set -euo pipefail

DECK_REPO="${1:-OpenC3/pr-decks}"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

gh repo create "$DECK_REPO" --public \
  --description "Slide decks summarizing pull requests, generated by the pr-deck skill"

# Initial commit on main: a README and .nojekyll so Pages serves files as-is
cat > "$WORK/README.md" <<'EOF'
# PR decks

Slide decks that summarize pull requests, generated by the `pr-deck` Claude Code
skill and published with GitHub Pages. Each deck lives at
`<owner>/<repo>/pr-<number>/<head-sha>/`, so decks from any source repo can share
this site.

Files here are generated. Don't edit them by hand.
EOF
python3 -I - "$WORK/README.md" > "$WORK/readme.json" <<'PY'
import base64, json, sys
print(json.dumps({"message": "Initial commit", "content": base64.b64encode(open(sys.argv[1], "rb").read()).decode()}))
PY
gh api -X PUT "repos/$DECK_REPO/contents/README.md" --input "$WORK/readme.json" >/dev/null
gh api -X PUT "repos/$DECK_REPO/contents/.nojekyll" -f message="Serve files as-is" -f content="" >/dev/null

gh api -X POST "repos/$DECK_REPO/pages" -f "source[branch]=main" -f "source[path]=/" --jq .html_url
